    case HALL_VILLAGE_ID:
        return static_cast<long>(
            player->m_ai.m_resourceValue[GOLD] * 3500.0 + value);
    case HALL_TOWN_ID:
        return static_cast<long>(
            player->m_ai.m_resourceValue[GOLD] * 3500.0 + value);
    case HALL_CITY_ID:
        return static_cast<long>(
            player->m_ai.m_resourceValue[GOLD] * 7000.0 + value);
    case HALL_CAPITOL_ID:
        return static_cast<long>(
            player->m_ai.m_resourceValue[GOLD] * 14000.0 + value);
