    const TCreatureTypeTraits* traits;
    TCreatureType creature;
    long funds[7];
    long bestValue = 0;
    union {
        // Before normalization: index.
        int m_index;
        // Before normalization: id.
        type_building_id m_id;
    } building, bestBuilding;
    __int64 buildMask = currentTown->getBuildableMask();
